      const code=row.dataset.finishMediaCode;
      const spec=animatedMedia[code];
      const stage=q('.finish-preview-stage',row);
      if(!spec || !stage)return;
      const fallback=Array.from(stage.children).filter(el=>!el.matches('.finish-preview-title,.finish-preview-caption,.finish-preview-price'));
      fallback.forEach(el=>el.classList.add('finish-rev9-static-fallback'));
