  function finishCatalogueControls(report) {
    report.catalogueScrollers=qa('.hist-shop-catalog').map(catalogue=>{
      const choices=qa(':scope>.hist-catalog-choice',catalogue);
      if(!choices.length)return null;
      catalogue.classList.add('finish-native-catalogue');
      const scroller=document.createElement('div');scroller.className='finish-catalog-scroll';
      scroller.setAttribute('role','group');scroller.setAttribute('aria-label','Catalogue items');
      scroller.tabIndex=0;
      const controls=[];
      const sync=()=>{controls.forEach(({button,direction})=>{button.disabled=direction<0?scroller.scrollTop<=0:scroller.scrollTop+scroller.clientHeight>=scroller.scrollHeight-1;});};
      [['up','Scroll up',-1,false],['top','First items',-1,true],['down','Scroll down',1,false],['bottom','Last items',1,true]].forEach(([name,label,direction,all])=>{
        const button=document.createElement('button');button.type='button';
        button.className='finish-catalog-nav finish-catalog-'+name;
        button.setAttribute('aria-label',label);button.title=label;
        button.textContent=label;
        button.addEventListener('click',()=>{
          scroller.scrollTop=all?(direction<0?0:scroller.scrollHeight):scroller.scrollTop+direction*105;
          sync();
        });
        controls.push({button,direction});catalogue.appendChild(button);
      });
      choices.forEach(choice=>{
        scroller.appendChild(choice);
        choice.addEventListener('focus',()=>{
          const y=choice.offsetTop;
          if(y<scroller.scrollTop)scroller.scrollTop=y;
          else if(y+choice.offsetHeight>scroller.scrollTop+scroller.clientHeight)scroller.scrollTop=y+choice.offsetHeight-scroller.clientHeight;
          sync();
        });
      });
      catalogue.appendChild(scroller);scroller.addEventListener('scroll',sync,{passive:true});sync();
      return {source:'DoPs item_scroll_up/top/down/bottom +318px item_scroller',existingChoicesMoved:choices.length,originalChoiceNodesPreserved:choices.every(choice=>choice.parentNode===scroller),newBusinessControls:0,newTimers:0,scrollStep:105,scrollTiming:'Immediate browser scroll; missing original itemlist.js prevents a claim of exact historical timing.'};
    }).filter(Boolean);
  }
